arguments.file_text:
@using sv_870fb6d262194b3cab0582a8e0c1351e.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == SelectedChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel)" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? SelectedChannelId { get; set; }
    [Parameter] public EventCallback<Channel> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2f3136;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #8e9297;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-list::-webkit-scrollbar {
    width: 4px;
}

.channel-list::-webkit-scrollbar-thumb {
    background-color: #202225;
    border-radius: 2px;
}

@using sv_870fb6d262194b3cab0582a8e0c1351e.Services

<div class="message-area">
    <div class="message-area-header">
        @if (Channel is not null)
        {
            <h2># @Channel.Name</h2>
            <span class="header-desc">@Channel.Description</span>
        }
    </div>

    <div class="message-list">
        @if (HasMore)
        {
            <div class="load-more-container">
                @if (IsLoadingMore)
                {
                    <span class="loading-text">Loading older messages…</span>
                }
                else
                {
                    <button class="load-more-btn" @onclick="OnLoadMore">
                        ⬆ Load older messages
                    </button>
                }
            </div>
        }

        @foreach (var message in Messages)
        {
            @if (message.ReplyToId is null)
            {
                <MessageBubble Message="message"
                               ReplyCount="GetReplyCount(message.Id)"
                               OnReplyClick="() => OnOpenThread.InvokeAsync(message)"
                               OnThreadClick="() => OnOpenThread.InvokeAsync(message)"
                               OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name}")"
                  ButtonText="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<Message> OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
}

.message-area-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
    min-height: 48px;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #fff;
    white-space: nowrap;
}

.header-desc {
    font-size: 0.82rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
}

.message-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-thumb {
    background-color: #202225;
    border-radius: 3px;
}

.load-more-container {
    text-align: center;
    padding: 12px;
}

.load-more-btn {
    background: none;
    border: 1px solid #4f545c;
    color: #b9bbbe;
    padding: 6px 16px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.82rem;
    transition: all 0.15s;
}

.load-more-btn:hover {
    background-color: rgba(255, 255, 255, 0.04);
    color: #dcddde;
    border-color: #72767d;
}

.loading-text {
    color: #72767d;
    font-size: 0.82rem;
}

@using sv_870fb6d262194b3cab0582a8e0c1351e.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageBubble Message="reply"
                               OnReact="(emoji) => OnReactInThread.InvokeAsync((reply.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonText="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactInThread { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    border-left: 1px solid #202225;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.thread-root {
    padding: 12px 16px;
    border-bottom: 1px solid #2f3136;
    background-color: rgba(0, 0, 0, 0.1);
}

.root-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
    margin-bottom: 4px;
}

.root-content {
    color: #dcddde;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 8px 16px;
    gap: 8px;
}

.thread-divider::before,
.thread-divider::after {
    content: "";
    flex: 1;
    height: 1px;
    background-color: #3f4147;
}

.thread-divider span {
    font-size: 0.75rem;
    color: #72767d;
    white-space: nowrap;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-replies::-webkit-scrollbar {
    width: 4px;
}

.thread-replies::-webkit-scrollbar-thumb {
    background-color: #202225;
