.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
}

.message-area-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
    min-height: 48px;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #fff;
    white-space: nowrap;
}

.header-desc {
    font-size: 0.82rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
}

.message-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-thumb {
    background-color: #202225;
    border-radius: 3px;
}

.load-more-container {
    text-align: center;
    padding: 12px;
}

.load-more-btn {
    background: none;
    border: 1px solid #4f545c;
    color: #b9bbbe;
    padding: 6px 16px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.82rem;
    transition: all 0.15s;
}

.load-more-btn:hover {
    background-color: rgba(255, 255, 255, 0.04);
    color: #dcddde;
    border-color: #72767d;
}

.loading-text {
    color: #72767d;
    font-size: 0.82rem;
}

